import { Model, ModelType, MxCloudGenAIModelFields, Provider } from "../types/model";




export function createNewModel(): Model {
    return {
        modelDocumentUUID: crypto.randomUUID(),
        type: "" as ModelType,
        name: "",
        displayName: "",
        provider: "MxCloudGenAI" as Provider, // Preselct MxCloudGenAI as default provider
        providerFields: createNewMxCloudGenAIModelFields()
    };
}
export const createNewMxCloudGenAIModelFields = (): MxCloudGenAIModelFields => {
    return {
        environment: '',
        deepLinkURL: '',
        key: '',
        keyImportHelper: '',
        keyId: '',
        keyName: '',
        resourceName: ''
    }
}